const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',fuel:'M4 3h10v18H4z M6 6h6v5H6z M14 8l4 3v6a2 2 0 0 0 4 0V8l-3-3 M2 21h14',tractor:'M4 16h9l3-7h4v7h-3 M3 7h8v9 M7 7V3 M5 3h5 M2 13h3 M9 19a3 3 0 1 0 0-6 3 3 0 0 0 0 6 M19 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4',sync:'M20 8a8 8 0 0 0-14-4L3 7 M3 2v5h5 M4 16a8 8 0 0 0 14 4l3-3 M21 22v-5h-5',bell:'M18 8a6 6 0 0 0-12 0c0 8-3 8-3 10h18c0-2-3-2-3-10 M10 21h4',plus:'M12 5v14 M5 12h14',download:'M12 3v12 M7 10l5 5 5-5 M5 17v4h14v-4',search:'M21 21l-6-6 M18 10a8 8 0 1 0-16 0 8 8 0 0 0 16 0',check:'M5 12l4 4L19 6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 4 4 1 1 5-4 3-1 5H9l-1-4-4-1-1-5 4-3z',leaf:'M20 3C8 2 1 8 5 16s16 1 15-13 M5 20L16 9',arrow:'M5 12h14 M14 7l5 5-5 5',x:'M6 6l12 12 M18 6L6 18',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M18 5a4 4 0 0 1 0 7 M18 15a4 4 0 0 1 4 4v2',file:'M6 3h9l4 4v14H6z M14 3v5h5 M9 12h7 M9 16h7',shield:'M12 2l9 4v7q-2 6-9 9-7-3-9-9V6z M7 12l3 3 6-6'};
const icon=(n)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const navigationIcons={
 checklists:'<rect x="5" y="4" width="15" height="17" rx="2"/><path d="M9 4V2h7v2M8 10l1.5 1.5L12 9M14 10h3M8 16l1.5 1.5L12 15M14 16h3"/>',
 dashboard:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="5" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="12" width="7" height="9" rx="1.5"/>',
 history:'<path d="M4 21V5a2 2 0 0 1 2-2h6a2 2 0 0 1 2 2v16M2 21h14M14 10h2a2 2 0 0 1 2 2v5a2 2 0 0 0 4 0V8l-3-3M19 5v4h3"/><rect x="7" y="6" width="4" height="5" rx=".5"/>',
 operations:'<path d="M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4"/>',
 occurrences:'<path d="m12 3 10 18H2L12 3Z M12 9v5 M12 17h.01"/>',
 fleets:'<path d="M4 14V5h7v10M4 5h9M11 11h7l3 5v2h-3M9 18h7M3 10h8M15 11V7"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="18" r="2"/>',
 pending:'<path d="M20 8a8 8 0 0 0-13.7-3M20 3v5h-5M4 16a8 8 0 0 0 13.7 3M4 21v-5h5"/>',
 settings:'<path d="M9.8 3h4.4l.7 2.5 2.2 1.3 2.5-.7 2.2 3.8-1.8 1.8v2.6l1.8 1.8-2.2 3.8-2.5-.7-2.2 1.3-.7 2.5H9.8l-.7-2.5-2.2-1.3-2.5.7-2.2-3.8 1.8-1.8v-2.6L2.2 9.9l2.2-3.8 2.5.7 2.2-1.3L9.8 3Z"/><circle cx="12" cy="13" r="3"/>'
};
const navigationIcon=id=>`<span class="nav-icon-wrap"><svg class="nav-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${navigationIcons[id]}</svg></span>`;
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,dec=1)=>Number(v||0).toLocaleString('pt-BR',{maximumFractionDigits:dec});
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo'}).format(new Date());
const date=(v)=>v?new Date(v+'T12:00:00').toLocaleDateString('pt-BR'):'—';
const fieldMode=!location.pathname.endsWith('/admin.html');
let checklistRecords=[],checklistLoading=null;
let receipt=null,serverOperations=[],fleetSearch='',dashboardDays=30;
const operationFilters={transfer:{fleet:'',operator:'',from:'',to:''},occurrence:{fleet:'',operator:'',from:'',to:''}};
const viewTitles={dashboard:'VISÃO GERAL',history:'ABASTECIMENTOS',operations:'TRANSFERÊNCIA',occurrences:'OCORRÊNCIAS',fleets:'FROTAS',settings:'CONFIGURAÇÕES',checklists:'CHECKLIST',pending:'PENDÊNCIAS'};
let db,session=null,serverRecords=[],queue=[],view='dashboard',busy=false,connected=false,ready=false,installPrompt=null,search='',fleetFilter='',statusFilter='',periodFilter='month',lastChecked=null,draft={},editId=null;
installUppercaseInputs();
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',6000)}
async function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('abencoada-diesel',1);r.onupgradeneeded=()=>{r.result.createObjectStore('queue',{keyPath:'id'});r.result.createObjectStore('meta',{keyPath:'key'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function storeOp(store,mode,fn){return new Promise((resolve,reject)=>{const tx=db.transaction(store,mode),r=fn(tx.objectStore(store));let value;r.onsuccess=()=>value=r.result;tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
const meta=async(key)=>((await storeOp('meta','readonly',s=>s.get(key)))||{}).value;
const putMeta=(key,value)=>storeOp('meta','readwrite',s=>s.put({key,value}));
const userKey=(x)=>`${session.user.id}:${x}`;
async function loadLocal(){const savedDays=Number(await meta(userKey('dashboard-days')));if(dashboardPeriods.includes(savedDays))dashboardDays=savedDays;serverRecords=(await meta(userKey('records')))||[];serverOperations=(await meta(userKey('operations')))||[];checklistRecords=(await meta(userKey('checklists')))||[];queue=(await storeOp('queue','readonly',s=>s.getAll())).filter(r=>fieldMode||r.userId===session.user.id||r.submissionKey).sort((a,b)=>(a.createdAt||'').localeCompare(b.createdAt||''));draft=(await meta(userKey('draft')))||{};lastChecked=await meta(userKey('seen'));if(!lastChecked){lastChecked=new Date().toISOString();await putMeta(userKey('seen'),lastChecked)}}
async function refreshSession(){if(fieldMode){const s=await fieldApi('session');session={...session,...s};await putMeta('field-session',s);connected=true;return}const s=await api('session');if(session&&s.user.id!==session.user.id){await saveDraft();session=s;await loadLocal();editId=null;view=fieldMode?'new':admin()?'dashboard':'denied';shell()}else session=s;await putMeta('session',s);connected=true}
function admin(){return session?.user.role==='admin'}
function allRecords(){const map=new Map(serverRecords.map(r=>[r.id,{...r,status:'synced'}]));for(const r of queue)map.set(r.id,{...r,status:r.error?'error':'pending'});return [...map.values()].sort((a,b)=>(b.received_at||b.createdAt||'').localeCompare(a.received_at||a.createdAt||''))}
function filtered(){return allRecords().filter(r=>(!fleetFilter||r.fleet===fleetFilter)&&(!search||`${r.fleet} ${r.operator} ${r.date}`.toLowerCase().includes(search.toLowerCase()))&&(!statusFilter||r.status===statusFilter)&&(periodFilter==='all'||(periodFilter==='today'?r.date===today():r.date.slice(0,7)===today().slice(0,7))))}
function unread(){return [...serverRecords,...serverOperations,...checklistRecords].filter(r=>r.received_at>lastChecked)}
function readings(fleet,except){const f=session.fleets.find(f=>f.id===fleet)||{};const max={engine:Number(f.last_engine||0),elevator:Number(f.last_elevator||0),km:Number(f.last_km||0)};for(const r of allRecords())if(r.fleet===fleet&&r.id!==except)for(const k of Object.keys(max))max[k]=Math.max(max[k],Number(r[k]||0));return max}
function fleetOptions(selected='',all=false){return (all?'<option value="">Todas as frotas</option>':'<option value="">Selecione a máquina</option>')+session.fleets.filter(f=>f.active).map(f=>`<option value="${esc(f.id)}" ${f.id===selected?'selected':''}>${esc(f.id)} · ${esc(f.name)}</option>`).join('')}
function statusPill(r){return `<span class="pill ${r.status==='synced'?'':r.status==='error'?'error':'pending'}">${icon(r.status==='synced'?'check':r.status==='error'?'shield':'clock').replace('<svg','<svg width="10" height="10"')} ${r.status==='synced'?'Sincronizado':r.status==='error'?'Conferir leitura':'Pendente'}</span>`}
function connectionHTML(){return `<span class="status ${connected?'':'offline'}"><span class="dot"></span>${connected?'Conectado':'Sem conexão'}</span>`}
function navItem(id,title){return `<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${navigationIcon(id)}<span>${title}</span></button>`}
function shell(){if(fieldMode)return fieldShell();if(!admin()){app.innerHTML='<section class="card boot-login"><h1>Acesso restrito ao gestor</h1><p>Use o aplicativo Android para registrar abastecimentos.</p></section>';return}app.innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><img src="./logo-abencoada.png" alt="Abençoada Agrícolas"><p>CONTROLE DE COMBUSTÍVEL</p></div><nav class="nav">${admin()?navItem('dashboard','Visão geral'):''}${navItem('history','Abastecimentos')}${navItem('operations','Transferências')}${navItem('occurrences','Ocorrências')}${admin()?navItem('fleets','Frotas'):''}${navItem('checklists','Checklist')}${admin()?navItem('settings','Configurações'):''}</nav><div class="side-bottom"><div class="profile"><span class="avatar">${esc(session.user.name.slice(0,2).toUpperCase())}</span><div><strong>${esc(session.user.name.slice(0,23))}</strong><small>${admin()?'':'Operador de campo · '}<a href="#" data-signout>Sair</a></small></div></div></div></aside><div class="main"><header class="topbar"><h1 class="topbar-title">${viewTitles[view]||'CONTROLE DE COMBUSTÍVEL'}</h1><div class="top-actions"><span id="connection">${connectionHTML()}</span><button class="icon-btn" id="notifications" aria-label="Notificações">${icon('bell')}${unread().length?`<span class="badge">${unread().length}</span>`:''}</button></div></header><main class="content" id="content"></main></div></div>`;bindSignOut();document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));document.querySelector('#notifications').onclick=showNotifications;renderContent()}
async function navigate(v){if(view==='new')await saveDraft();view=v;search='';fleetFilter='';statusFilter='';if(v==='new'){editId=null;draft=(await meta(userKey('draft')))||{}}shell()}

function fieldShell(){
 document.body.classList.add('field-page');
 app.innerHTML=`<header class="field-header"><a href="./index.html" class="field-brand"><img src="./logo-abencoada.png" alt="Abençoada Agrícola"></a></header><main class="field-content"><div class="field-intro"><h1>Registrar abastecimento</h1></div><div id="field-feedback" aria-live="polite"></div><form id="fuel-form" class="field-form">${fieldFormHTML()}</form><div id="field-queue" aria-live="polite"></div><footer class="field-footer"></footer></main>`;
 bindForm();updateFieldStatus();
}
function fieldFormHTML(){
 const d=draft||{},m=readings(d.fleet,editId);
 const reading=(k,label,unit)=>`<label>${label}<input type="number" name="${k}" required min="0" max="1000000000" step="0.01" inputmode="decimal" value="${esc(d[k]??'')}" placeholder="Digite a leitura"><small id="last-${k}">Última: ${num(m[k])} ${unit}</small></label>`;
 const number=(k,label)=>`<label>${label}<input type="number" name="${k}" required min="${k==='liters'?'0.01':'0'}" max="1000000000" step="0.01" inputmode="decimal" value="${esc(d[k]??'')}" placeholder="0,00"></label>`;
 return `${!session.fleets.length?'<div class="notice">Nenhuma frota disponível. Peça ao gestor para cadastrar sua máquina.</div>':''}<div class="field-fields"><label>Nome do trabalhador<input name="operator" type="text" autocomplete="name" required minlength="2" maxlength="120" value="${esc(d.operator||'')}" placeholder="Digite seu nome completo"></label><label>Máquina / frota<input name="fleet" type="text" list="fleet-codes" autocomplete="off" required maxlength="30" value="${esc(d.fleet||'')}" placeholder="Digite o código da frota"><datalist id="fleet-codes">${session.fleets.filter(f=>f.active).map(f=>`<option value="${esc(f.id)}">${esc(f.name)}</option>`).join('')}</datalist></label>${reading('engine','Horímetro do motor','h')}${reading('elevator','Horímetro do elevador','h')}${reading('km','Quilometragem (KM)','km')}${number('start','Início do registro')}${number('end','Final do registro')}${number('liters','Quantidade de litros')}</div><p id="capacity-warning" class="notice" role="status" hidden></p><p id="form-error" class="field-error" role="alert"></p><div class="field-send"><button class="btn primary" id="submit-record" type="submit" ${!session.fleets.length?'disabled':''}>${icon('check')} ${editId?'Corrigir e enviar':'Enviar abastecimento'}</button></div>`;
}
function updateFieldStatus(){
 const status=document.getElementById('field-connection');if(status)status.textContent=connected?(ready?'Online · offline pronto':'Online'):(ready?'Sem internet. O registro será guardado neste celular.':'Sem conexão. Guarde este celular até confirmar o envio.');
 const feedback=document.getElementById('field-feedback');if(feedback){let text='',kind='';if(receipt){const pending=queue.find(r=>r.id===receipt.id);kind=pending?.error?'error':pending?'saved':'sent';text=pending?.error?'Confira as leituras antes de enviar.':pending?'Salvo neste celular. Será enviado quando a internet voltar.':'Enviado para a administração.';feedback.innerHTML=`<div class="field-result ${kind}">${icon(kind==='error'?'shield':'check')}<div><strong>${text}</strong><small>Frota ${esc(receipt.fleet)} · ${num(receipt.liters)} litros</small></div></div>`}else feedback.innerHTML=''}
 const q=document.getElementById('field-queue');if(q){q.innerHTML=queue.length?`<section class="field-pending"><div class="field-pending-head"><strong>${queue.length} registro${queue.length>1?'s':''} neste celular</strong><button class="link-btn" id="field-retry" ${busy?'disabled':''}>${busy?'Enviando…':'Tentar enviar'}</button></div>${queue.filter(r=>r.error).map(r=>`<div class="field-rejected"><p><b>Frota ${esc(r.fleet)}</b> · ${num(r.liters)} litros</p><p>${esc(r.error)}</p><button class="btn" data-correct="${r.id}">Conferir e corrigir</button></div>`).join('')}</section>`:'';const retry=document.querySelector('#field-retry');if(retry)retry.onclick=()=>sync();document.querySelectorAll('[data-correct]').forEach(b=>b.onclick=async()=>{await saveDraft();const r=queue.find(r=>r.id===b.dataset.correct);if(r){draft=r;editId=r.id;receipt=null;view='new';fieldShell();window.scrollTo({top:0,behavior:'smooth'})}})}
}

function heading(title,subtitle,actions=''){if(viewTitles[view])return actions?`<div class="page-heading page-tools"><div class="heading-actions">${actions}</div></div>`:'';return `<div class="page-heading"><div><h1>${title}</h1></div><div class="heading-actions">${actions}</div></div>`}
const newButton=()=>'';
function offlineBanner(){return queue.length?`<div class="banner"><b>${queue.length} registro${queue.length>1?'s':''} aguardando envio</b><button class="link-btn" id="sync-banner">Ver pendências →</button></div>`:''}
function renderContent(){const c=document.querySelector('#content');if(view==='dashboard')c.innerHTML=dashboard();else if(view==='new')c.innerHTML=formHTML();else if(view==='history')c.innerHTML=historyHTML();else if(view==='fleets')c.innerHTML=fleetsHTML();else if(view==='operations'||view==='occurrences'){c.innerHTML=heading(view==='occurrences'?'Ocorrências':'Transferências','','<button class="btn" id="removed-records">Excluídos</button>')+'<section class="card" id="operations-list">Carregando…</section>';loadOperationsList()}else if(view==='checklists'){c.innerHTML=checklistPage(session.fleets);checklistLoading=loadChecklists({api,fleets:session.fleets,dialog,toast,refreshSession,onRecords:cacheChecklists})}else if(view==='pending')c.innerHTML=pendingHTML();else c.innerHTML=settingsHTML();bindContent();const period=document.querySelector('#dashboard-period');if(period)period.onchange=async()=>{dashboardDays=Number(period.value);renderContent();await putMeta(userKey('dashboard-days'),dashboardDays).catch(()=>{})};const removed=document.querySelector('#removed-records');if(removed)removed.onclick=showRemovedRecords;if(view==='new')bindForm();if(view==='settings')loadMembers()}
function isTestRecord(r){return r.is_test===true||session.fleets.some(f=>f.id===r.fleet&&f.is_test)}
function operationalRecords(){return allRecords()}
function dashboardRecords(){const range=dashboardRange(today(),dashboardDays);return operationalRecords().filter(r=>r.date>=range.start&&r.date<=range.end)}
function dashboard(){const rs=dashboardRecords(),synced=rs.filter(r=>r.status==='synced'),total=synced.reduce((s,r)=>s+r.liters,0),active=new Set(synced.map(r=>r.fleet)).size;const sums=session.fleets.map(f=>({...f,total:synced.filter(r=>r.fleet===f.id).reduce((s,r)=>s+r.liters,0),count:synced.filter(r=>r.fleet===f.id).length})).sort((a,b)=>b.total-a.total);
return offlineBanner()+checklistAlertHTML()+`<div class="metrics">${metric('Combustível abastecido',`${num(total)} <small>L</small>`,'Últimos '+dashboardDays+' dias','fuel')}${metric('Abastecimentos',synced.length,'','file')}${metric('Frotas abastecidas',active,`${session.fleets.length} frotas cadastradas`,'tractor')}${metric('Aguardando envio',queue.length,queue.some(r=>r.error)?'Há leituras para conferir':'','sync')}</div><div class="two-col"><section class="card"><div class="card-head"><div><h2>Volume de combustível</h2></div><span class="period">${dashboardDays} DIAS${dashboardDays>7?' · A CADA 7 DIAS':''}</span></div>${chart()}</section><section class="card"><div class="card-head"><div><h2>Abastecimento por frota</h2></div><button class="link-btn" id="view-fleets">Ver todas →</button></div><div class="fleet-summary">${sums.length?sums.slice(0,4).map(f=>`<div class="fleet-row"><div class="machine-icon">${icon('tractor')}</div><div><b>Frota ${esc(f.id)}</b><small>${esc(f.name)}</small></div><span class="amount">${num(f.total)} <small>L</small></span></div>`).join(''):'<div class="empty">Cadastre sua primeira frota<br>para começar a operação.</div>'}</div></section></div>${averagesHTML()}<section class="card"><div class="card-head"><div><h2>Últimos abastecimentos</h2></div><button class="link-btn" id="view-history">Ver todos →</button></div>${table(rs.slice(0,5))}<div class="table-footer"><span>${new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long'})}</span></div></section><div class="dashboard-footer"><label class="dashboard-period">PERÍODO<select id="dashboard-period" aria-label="Período da visão geral">${dashboardPeriods.map(days=>`<option value="${days}" ${dashboardDays===days?'selected':''}>ÚLTIMOS ${days} DIAS</option>`).join('')}</select></label><button class="btn" id="export">${icon('download')} Exportar</button></div>`}
function metric(title,value,foot,i){return `<div class="metric"><div class="metric-label">${title}<span class="metric-icon">${icon(i)}</span></div><strong>${value}</strong>${foot?`<div class="metric-foot">${foot}</div>`:''}</div>`}
function chart(){const buckets=dashboardVolumes(serverRecords,today(),dashboardDays),label=v=>v.slice(8,10)+'/'+v.slice(5,7),max=Math.max(100,...buckets.map(b=>b.total));return `<div class="chart"><div class="chart-y"><span>${num(max,0)} L</span><span>${num(max*.75,0)}</span><span>${num(max*.5,0)}</span><span>${num(max*.25,0)}</span><span>0</span></div><div class="bars" style="min-width:${buckets.length*30}px">${buckets.map(b=>`<div class="bar-wrap"><div class="bar" style="height:${b.total/max*100}%" title="${label(b.start)}${b.start===b.end?'':' a '+label(b.end)}: ${num(b.total)} L"></div><span class="bar-label">${label(b.start)}</span></div>`).join('')}</div></div>`}
function table(rs,detail=true){if(!rs.length)return `<div class="empty">${icon('fuel')}<br><strong>Nenhum abastecimento por aqui ainda.</strong></div>`;return `<div class="table-wrap"><table><thead><tr><th>DATA</th><th>FROTA</th><th>TRABALHADOR / ASSINATURA</th><th>LITROS</th><th>SITUAÇÃO</th>${detail?'<th></th>':''}</tr></thead><tbody>${rs.map(r=>`<tr><td>${date(r.date)}</td><td><strong>${esc(r.fleet)}</strong></td><td>${esc(r.operator)}</td><td><strong>${num(r.liters)} L</strong>${r.capacity_warning_confirmed?'<br><span class="pill pending">Acima da capacidade</span>':''}</td><td>${statusPill(r)}</td>${detail?`<td><button class="link-btn" data-detail="${r.id}">${r.status==='error'?'Conferir':'Detalhes'} →</button></td>`:''}</tr>`).join('')}</tbody></table></div>`}
function filtersHTML(){return `<div class="table-tools"><div class="search">${icon('search')}<input id="search" placeholder="Buscar frota ou trabalhador" aria-label="Buscar" value="${esc(search)}"></div><select class="filter" id="fleet-filter" aria-label="Filtrar por frota">${fleetOptions(fleetFilter,true)}</select><select class="filter" id="period-filter" aria-label="Período"><option value="month" ${periodFilter==='month'?'selected':''}>Este mês</option><option value="today" ${periodFilter==='today'?'selected':''}>Hoje</option><option value="all" ${periodFilter==='all'?'selected':''}>Todo o período</option></select><select class="filter" id="status-filter" aria-label="Situação"><option value="">Todas as situações</option><option value="synced" ${statusFilter==='synced'?'selected':''}>Sincronizados</option><option value="pending" ${statusFilter==='pending'?'selected':''}>Pendentes</option><option value="error" ${statusFilter==='error'?'selected':''}>Conferir leitura</option></select></div>`}
function historyHTML(){return heading('Abastecimentos','Histórico organizado por frota e trabalhador.',`<button class="btn" id="print">${icon('file')} Imprimir</button><button class="btn" id="export">${icon('download')} Exportar</button>${newButton()}<button class="btn" id="removed-records">Excluídos</button>`)+`<section class="card"><div class="card-head"><h2>Todos os registros</h2><span class="subtitle">${filtered().length} registros</span></div>${filtersHTML()}<div id="rows">${table(filtered())}</div></section>`}
function formHTML(){const d=draft||{},m=readings(d.fleet,editId),field=(key,title,unit)=>`<label>${title} <span class="required">*</span><input type="number" name="${key}" required min="0" max="1000000000" step="0.01" inputmode="decimal" value="${esc(d[key]??'')}" placeholder="0,00"><small id="last-${key}">Última leitura: ${num(m[key])} ${unit}</small></label>`;
return heading(editId?'Conferir abastecimento':'Novo abastecimento','')+`<div class="form-layout"><form class="card" id="fuel-form"><div class="form-section"><div class="section-title"><span class="number">01</span><h2>Identificação</h2></div><div class="form-grid"><label>Data <span class="required">*</span><input type="date" name="date" value="${esc(d.date||today())}" required ${session.rules.futureDate?'':`max="${today()}"`}></label><label>Frota <span class="required">*</span><select name="fleet" required>${fleetOptions(d.fleet)}</select></label><label class="full">Trabalhador e assinatura automática<input value="${esc(session.user.name)}" readonly><small>O servidor confirma a assinatura a partir da conta que está conectada.</small></label></div></div><div class="form-section"><div class="section-title"><span class="number">02</span><h2>Leituras da máquina</h2></div><div class="form-grid three">${field('engine','Horímetro motor','h')}${field('elevator','Horímetro elevador','h')}${field('km','Quilometragem','km')}</div></div><div class="form-section"><div class="section-title"><span class="number">03</span><h2>Abastecimento</h2></div><div class="form-grid three"><label>Início reg. <span class="required">*</span><input name="start" type="number" required min="0" max="1000000000" step="0.01" inputmode="decimal" value="${esc(d.start??'')}" placeholder="0,00"></label><label>Final reg. <span class="required">*</span><input name="end" type="number" required min="0" max="1000000000" step="0.01" inputmode="decimal" value="${esc(d.end??'')}" placeholder="0,00"></label><label>Litros <span class="required">*</span><input name="liters" type="number" required min="0.01" max="1000000000" step="0.01" inputmode="decimal" value="${esc(d.liters??'')}" placeholder="0,00"></label><label class="full">Observações <span class="subtitle">(opcional)</span><textarea name="notes" rows="3" maxlength="1000" placeholder="Alguma informação sobre este abastecimento?">${esc(d.notes||'')}</textarea></label></div></div><div class="form-section"><div class="section-title"><span class="number">04</span><h2>Confirmação</h2></div><div class="banner" style="margin:0"><div class="banner-icon">${icon('check').replace('<svg','<svg width="19" height="19"')}</div><div><b>Assinado por ${esc(session.user.name)}</b><p>A identidade da conta e o horário de recebimento acompanham o registro.</p></div></div></div><p id="capacity-warning" class="notice" role="status" hidden></p><p class="error-message" id="form-error" role="alert"></p><div class="form-footer"><span class="subtitle">${ready?'Aplicativo disponível offline':'Preparando acesso offline…'}</span><button class="btn primary" type="submit" id="submit-record">${icon('check')} Salvar abastecimento</button></div></form></div>`}
function fleetsHTML(){return heading('Frotas','',`<button class="btn" id="print-fleet-qr">Imprimir QR Codes</button><button class="btn primary" id="add-fleet">${icon('plus')} Cadastrar frota</button>`)+`<section class="card fleet-search"><label for="fleet-search">Pesquisar frota ou modelo</label><input id="fleet-search" type="search" placeholder="Código, nome, modelo ou tipo" value="${esc(fleetSearch)}"></section><div id="fleet-list">${fleetCardsHTML()}</div>`}
function fleetCardsHTML(){const term=fleetSearch.trim().toLocaleLowerCase('pt-BR'),fleets=session.fleets.filter(f=>!term||[f.id,f.name,f.model,f.type].join(' ').toLocaleLowerCase('pt-BR').includes(term));return fleets.length?`<div class="cards-grid">${fleets.map(f=>{const rs=serverRecords.filter(r=>r.fleet===f.id),m=readings(f.id);return `<article class="card fleet-card"><div class="fleet-card-title"><div class="machine-icon">${icon('tractor')}</div><span class="pill">${esc(f.type)}${f.active?'':' · Inativa'}</span></div><h3>${esc(f.name)}</h3><span class="code">FROTA ${esc(f.id)}</span>${f.model?`<p>MODELO: ${esc(f.model)}</p>`:''}<p>${f.tank_capacity?'CAPACIDADE: '+num(f.tank_capacity,2)+' L':'CAPACIDADE NÃO CADASTRADA'}</p>${f.tank_reference?.source?`<a class="link-btn" href="${esc(f.tank_reference.source)}" target="_blank" rel="noopener noreferrer">Referência do fabricante</a>`:''}<p>Motor: ${num(m.engine)} h${canUseElevator(f)&&fleetMeters(f).elevator?` · Elevador: ${num(m.elevator)} h`:""}<br>KM: ${num(m.km)}</p><div class="fleet-stats"><span>${rs.length} abastecimentos</span><strong>${num(rs.reduce((s,r)=>s+r.liters,0))} L</strong></div><button class="btn primary" data-edit-fleet="${esc(f.id)}">Editar frota</button><button class="btn" data-meter-fleet="${esc(f.id)}">Escolher leituras</button><button class="btn" data-fleet-qr="${esc(f.id)}">Gerar QR Code</button><button class="link-btn" data-fleet="${esc(f.id)}">Ver abastecimentos →</button></article>`}).join('')}</div>`:'<section class="card empty">Nenhuma frota encontrada.</section>'}
function bindFleetActions(){document.querySelectorAll('[data-edit-fleet]').forEach(b=>b.onclick=()=>editFleet(b.dataset.editFleet));document.querySelectorAll('[data-meter-fleet]').forEach(b=>b.onclick=()=>meterFieldsDialog(b.dataset.meterFleet));document.querySelectorAll('[data-fleet-qr]').forEach(b=>b.onclick=()=>fleetQrDialog(b.dataset.fleetQr));document.querySelectorAll('[data-fleet]').forEach(b=>b.onclick=()=>{view='history';fleetFilter=b.dataset.fleet;periodFilter='all';shell()})}
function editFleet(id){const f=session.fleets.find(f=>f.id===id);if(!f)return;dialog('Editar frota '+esc(id),`<form id="fleet-edit-form"><div class="form-grid"><label class="full">Nome<input name="name" required minlength="2" maxlength="80" value="${esc(f.name)}"></label><label class="full">Modelo<input name="model" maxlength="120" value="${esc(f.model||'')}"></label><label>Tipo<select name="type">${['Trator','Colhedora','Caminhão','Outro'].map(t=>`<option ${f.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Capacidade total dos tanques (L)<input name="tankCapacity" type="number" inputmode="decimal" min="0.01" max="100000" step="0.01" value="${esc(f.tank_capacity??'')}" placeholder="Não cadastrada"></label><label class="full">Situação<select name="active"><option value="true" ${f.active?'selected':''}>Ativa</option><option value="false" ${f.active?'':'selected'}>Inativa</option></select></label></div><p class="error-message" id="dialog-error" role="alert"></p><button class="btn primary" type="submit">Salvar frota</button></form>`);document.querySelector('#fleet-edit-form').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));await adminSave({action:'fleet-edit',id,...values,active:values.active==='true',tankCapacity:values.tankCapacity===''?null:Number(values.tankCapacity)})}}
function averagesHTML(){const summaries=consumptionSummary(serverRecords.filter(r=>r.date<=today()),dashboardRange(today(),dashboardDays).start).sort((a,b)=>b.liters-a.liters);const total=summaries.reduce((n,f)=>n+f.liters,0),count=summaries.reduce((n,f)=>n+f.count,0);return `<section class="card consumption-card"><div class="card-head"><h2>Médias · ${dashboardDays} dias</h2><span class="subtitle">${count?num(total/count,2)+' L / abastecimento':'Sem registros'}</span></div>${summaries.length?`<div class="table-wrap"><table><thead><tr><th>FROTA</th><th>MÉDIA L / ABAST.</th><th>KM / L ESTIMADO</th><th>L / H ESTIMADO</th></tr></thead><tbody>${summaries.map(f=>`<tr><td><strong>${esc(f.fleet)}</strong></td><td>${num(f.averageLiters,2)}</td><td>${f.kmPerLiter===null?'—':num(f.kmPerLiter,2)}</td><td>${f.litersPerHour===null?'—':num(f.litersPerHour,2)}</td></tr>`).join('')}</tbody></table></div><div class="table-footer">Consumo estimado pelas leituras disponíveis.</div>`:'<p class="empty">Sem abastecimentos neste período.</p>'}</section>`}

function pendingHTML(){return heading('Sincronização','Acompanhe o que já foi enviado e o que continua neste aparelho.',`<button class="btn primary" id="sync-now" ${busy?'disabled':''}>${icon('sync')} ${busy?'Sincronizando…':'Sincronizar agora'}</button>`)+offlineBanner()+`<div class="metrics" style="grid-template-columns:repeat(3,1fr)">${metric('Pendentes',queue.filter(r=>!r.error).length,'Prontos para envio','clock')}${metric('Conferir informações',queue.filter(r=>r.error).length,'Leituras bloqueadas pelo servidor','shield')}${metric('Enviados',serverRecords.length,'Confirmados no servidor','check')}</div><section class="card"><div class="card-head"><h2>Registros neste aparelho</h2></div>${queue.length?table(queue.map(r=>({...r,status:r.error?'error':'pending'}))):'<div class="empty">'+icon('check')+'<br><strong>Tudo em dia.</strong><br>Não há abastecimentos aguardando envio.</div>'}</section>`}
function settingsHTML(){return heading('Configurações','Gerencie a equipe e as regras da operação.')+`<div class="settings-grid"><section class="card"><div class="card-head"><h2>Regras</h2>${icon('shield').replace('<svg','<svg width="19" height="19"')}</div><label class="setting-row"><input id="rule-match" type="checkbox" ${session.rules.matchMeter?'checked':''}><div><b>Conferir diferença do medidor</b><p>Litros = final − início. Tolerância: 0,02 L (web).</p></div></label><label class="setting-row"><input id="rule-future" type="checkbox" ${session.rules.futureDate?'checked':''}><div><b>Permitir datas futuras</b></div></label><div class="form-footer"><button class="btn primary" id="save-rules">Salvar regras</button></div></section><section class="card"><div class="card-head"><div><h2>Equipe e acessos</h2></div><button class="link-btn" id="add-member">Adicionar +</button></div><div id="members"><p class="empty">Carregando equipe…</p></div></section><section class="card help-card"><h3>Avisos de novos registros</h3><button class="btn" id="enable-notifications">${icon('bell')} Ativar aviso do navegador</button></section></div>`}
function bindContent(){const bind=(id,fn)=>{const e=document.getElementById(id);if(e)e.onclick=fn};bind('new-button',()=>navigate('new'));bind('sync-banner',()=>navigate('pending'));bind('view-fleets',()=>navigate('fleets'));bind('view-history',()=>navigate('history'));bind('view-checklist-alerts',()=>navigate('checklists'));bind('sync-now',()=>sync());bind('export',exportCSV);bind('print',printRecords);bind('add-fleet',addFleet);bind('print-fleet-qr',()=>printFleetQrs(session.fleets.filter(f=>f.active)));document.querySelectorAll('[data-meter-fleet]').forEach(b=>b.onclick=()=>meterFieldsDialog(b.dataset.meterFleet));document.querySelectorAll('[data-fleet-qr]').forEach(b=>b.onclick=()=>fleetQrDialog(b.dataset.fleetQr));bind('add-member',addMember);bind('save-rules',saveRules);bind('install',install);bind('enable-notifications',async()=>{if(!('Notification'in window))return toast('Este navegador não oferece avisos. Use o sino no painel.');const permission=await Notification.requestPermission();toast(permission==='granted'?'Avisos ativados enquanto o painel estiver aberto.':'Os avisos continuam disponíveis no sino.')});bindDetails();bindFleetActions();const fs=document.querySelector('#fleet-search');if(fs)fs.oninput=()=>{fleetSearch=fs.value;document.querySelector('#fleet-list').innerHTML=fleetCardsHTML();bindFleetActions()};document.querySelectorAll('[data-fleet]').forEach(b=>b.onclick=()=>{view='history';fleetFilter=b.dataset.fleet;periodFilter='all';shell()});const s=document.querySelector('#search');if(s)s.oninput=()=>{search=s.value;renderRows()};for(const id of ['fleet-filter','period-filter','status-filter']){const e=document.getElementById(id);if(e)e.onchange=()=>{fleetFilter=document.getElementById('fleet-filter').value;periodFilter=document.getElementById('period-filter').value;statusFilter=document.getElementById('status-filter').value;renderRows()}}}
function renderRows(){document.querySelector('#rows').innerHTML=table(filtered());bindDetails()}
function bindDetails(){document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>details(b.dataset.detail))}
function formValues(){const f=document.querySelector('#fuel-form');return f?Object.fromEntries(new FormData(f).entries()):draft}
async function saveDraft(){if(document.querySelector('#fuel-form')){draft=formValues();await putMeta(userKey('draft'),draft)}}
function updateElevatorField(f){const fleet=session.fleets.find(v=>v.id===f.elements.fleet.value);const input=f.elements.elevator;if(!input)return;const hidden=Boolean(fleet&&!canUseElevator(fleet));input.closest('label').classList.toggle('meter-hidden',hidden);input.required=!hidden;if(hidden)input.value=readings(fleet.id,editId).elevator}
function bindForm(){const f=document.querySelector('#fuel-form');updateElevatorField(f);f.oninput=()=>{updateWebCapacity();clearTimeout(saveDraft.timer);saveDraft.timer=setTimeout(()=>saveDraft().catch(()=>toast('Não foi possível salvar o rascunho neste aparelho.')),400)};f.elements.fleet.oninput=()=>{updateElevatorField(f);const code=f.elements.fleet.value.trim().toUpperCase();const found=session.fleets.some(f=>f.active&&f.id===code);f.elements.fleet.setCustomValidity(code&&!found?'Informe o código de uma frota cadastrada.':'');const m=readings(code,editId);for(const k of ['engine','elevator','km'])document.getElementById('last-'+k).textContent=`Última leitura: ${num(m[k])} ${k==='km'?'km':'h'}`;saveDraft()};f.onsubmit=submitRecord;updateWebCapacity()}
async function submitRecord(e){e.preventDefault();const f=e.target,b=document.querySelector('#submit-record'),err=document.querySelector('#form-error');if(b.disabled)return;b.disabled=true;err.textContent='';try{const v=formValues();const r={id:editId||crypto.randomUUID(),userId:session.user.id,operator:fieldMode?String(v.operator||'').trim().replace(/\s+/g,' '):session.user.name,...(fieldMode?{submissionKey:editId?draft.submissionKey||crypto.randomUUID():crypto.randomUUID()}:{}),date:editId?draft.date:fieldMode?today():v.date,fleet:v.fleet.trim().toUpperCase(),engine:Number(v.engine),elevator:Number(v.elevator),km:Number(v.km),start:Number(v.start),end:Number(v.end),liters:Number(v.liters),notes:v.notes||'',createdAt:editId?draft.createdAt:new Date().toISOString()};if(fieldMode&&(r.operator.length<2||r.operator.length>120||!/[A-Za-zÀ-ÿ]/.test(r.operator)))throw new Error('Informe seu nome completo.');if(!session.fleets.some(f=>f.active&&f.id===r.fleet))throw new Error('Informe o código de uma frota cadastrada.');const m=readings(r.fleet,r.id);const names={engine:'Horímetro motor',elevator:'Horímetro elevador',km:'KM'};const low=Object.keys(m).filter(k=>r[k]<m[k]);if(low.length)throw new Error('Confira a informação: '+low.map(k=>`${names[k]} deve ser no mínimo ${num(m[k])}`).join('; ')+'.');if(r.end<=r.start)throw new Error('Confira as leituras: o registro final deve ser maior que o inicial.');if(r.liters<=0)throw new Error('Informe uma quantidade de litros maior que zero.');if(session.rules.matchMeter&&Math.abs(r.end-r.start-r.liters)>.02)throw new Error('Confira os litros: devem corresponder à diferença entre final e início.');await storeOp('queue','readwrite',s=>s.put(r));await putMeta(userKey('draft'),{});draft={};editId=null;await loadLocal();receipt={id:r.id,fleet:r.fleet,liters:r.liters};view=fieldMode?'new':'pending';shell();window.scrollTo({top:0,behavior:'smooth'});sync()}catch(error){err.textContent=error.message;b.disabled=false}}
async function fetchRecords(){if(admin()){await refreshChecklists();const operations=await api('operations-admin');const previous=new Set(serverOperations.map(o=>o.id));const freshOperations=operations.operations.filter(o=>!previous.has(o.id)&&o.received_at>lastChecked);serverOperations=operations.operations;await putMeta(userKey('operations'),serverOperations);if(freshOperations.length){const occurrences=freshOperations.filter(o=>o.kind==='occurrence');toast(occurrences.length?occurrences.length+' nova(s) ocorrência(s) recebida(s).':freshOperations.length+' nova(s) transferência(s) recebida(s).');if('Notification'in window&&Notification.permission==='granted'&&document.hidden){const operation=occurrences[0]||freshOperations[0];const reg=await navigator.serviceWorker?.getRegistration();if(reg)await reg.showNotification(operation.kind==='occurrence'?'NOVA OCORRÊNCIA':'NOVA TRANSFERÊNCIA',{body:operation.operator+' · LOCAL '+operation.local_code,icon:'./icon-192.png',tag:'operation-'+operation.id})}}}const data=await api('records');const ids=new Set(serverRecords.map(r=>r.id));const fresh=data.records.filter(r=>!ids.has(r.id)&&r.received_at>lastChecked);serverRecords=data.records;await putMeta(userKey('records'),serverRecords);if(fresh.length&&!fieldMode){toast(`${fresh.length} novo${fresh.length>1?'s':''} abastecimento${fresh.length>1?'s':''} recebido${fresh.length>1?'s':''}.`);if('Notification'in window&&Notification.permission==='granted'&&document.hidden){const reg=await navigator.serviceWorker?.getRegistration();if(reg)await reg.showNotification('NOVO ABASTECIMENTO',{body:`Frota ${fresh[0].fleet} · ${num(fresh[0].liters)} L`,icon:'./icon-192.png',tag:'diesel-'+fresh[0].id})}}}
async function sync(){if(busy||!session)return;busy=true;updateConnection();try{await refreshSession();for(const r of [...queue]){if(r.error)continue;try{if(r.submissionKey)await fieldApi('submit',r);else await api('records',{method:'POST',body:JSON.stringify(r)});const fleet=session.fleets.find(f=>f.id===r.fleet);if(fleet)for(const k of ['engine','elevator','km'])fleet['last_'+k]=Math.max(fleet['last_'+k]||0,r[k]);await putMeta(fieldMode?'field-session':'session',fieldMode?{fleets:session.fleets,rules:session.rules}:session);await storeOp('queue','readwrite',s=>s.delete(r.id));queue=queue.filter(q=>q.id!==r.id)}catch(error){if(error.status===422||error.status===409){r.error=error.message;r.serverReadings=error.data?.readings;await storeOp('queue','readwrite',s=>s.put(r));const f=session.fleets.find(f=>f.id===r.fleet);if(f&&r.serverReadings){for(const k of ['engine','elevator','km'])f['last_'+k]=Math.max(f['last_'+k]||0,r.serverReadings[k]||0);await putMeta(fieldMode?'field-session':'session',fieldMode?{fleets:session.fleets,rules:session.rules}:session)}toast(error.message)}else throw error}}if(!fieldMode)await fetchRecords();connected=true}catch(error){connected=false;if(error.status===401||error.status===403)toast('Entre novamente com sua conta para sincronizar. Os registros continuam neste aparelho.')}finally{busy=false;updateConnection();if(fieldMode){updateFieldStatus()}else if(view!=='new'){if(!admin())shell();else if(view==='fleets'&&document.activeElement?.id==='fleet-search'){document.querySelector('#fleet-list').innerHTML=fleetCardsHTML();bindFleetActions()}else if(view==='operations'||view==='occurrences'){renderOperationRows();const notices=document.querySelector('#notifications');if(notices)notices.innerHTML=icon('bell')+(unread().length?`<span class="badge">${unread().length}</span>`:'')}else if(view==='checklists'){updateChecklistRecords(checklistRecords);const notices=document.querySelector('#notifications');if(notices)notices.innerHTML=icon('bell')+(unread().length?`<span class="badge">${unread().length}</span>`:'')}else shell()}}}
function updateConnection(){if(fieldMode){updateFieldStatus();return}const e=document.getElementById('connection');if(e)e.innerHTML=connectionHTML();const b=document.getElementById('sync-now');if(b){b.disabled=busy;b.innerHTML=icon('sync')+(busy?' Sincronizando…':' Sincronizar agora')}}
function dialog(title,body){modal.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-btn" id="close-modal" aria-label="Fechar">${icon('x')}</button></div><div class="dialog-body">${body}</div>`;modal.showModal();document.querySelector('#close-modal').onclick=()=>modal.close()}
async function details(id){let r=allRecords().find(r=>r.id===id);if(!r)return;if(r.status==='synced')try{r={...r,...await api('records?id='+encodeURIComponent(id))}}catch{toast('Detalhes locais exibidos. A assinatura é confirmada no servidor.')}dialog('Abastecimento · Frota '+esc(r.fleet),`${r.error?`<div class="notice">${esc(r.error)}</div>`:''}<dl class="detail-grid">${[['Data e hora',new Date(r.created_at||r.createdAt).toLocaleString('pt-BR')],['Frota',r.fleet],...recordReadingDetails(r),...(r.local_code?[['Local',r.local_code],['Material',r.material_code],['Início da registradora',r.recorder_start===null?'—':num(r.recorder_start,2)],['Final da registradora',r.recorder_end===null?'—':num(r.recorder_end,2)]]:[]),['Litros',num(r.liters)+' L'],...(r.tank_capacity_at_record?[['Capacidade cadastrada',num(r.tank_capacity_at_record,2)+' L'],['Acima da capacidade',r.capacity_warning_confirmed?'Sim':'Não']]:[]),...(r.capture_mode==='quick'?[]:[['Início reg.',num(r.start)],['Final reg.',num(r.end)]]),[r.signature_source==='declared'||r.submissionKey?'Nome informado':'Assinatura da conta',r.signature||r.operator],['Recebido no servidor',r.received_at?new Date(r.received_at).toLocaleString('pt-BR'):'Aguardando confirmação']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${r.notes?`<p class="subtitle">Observações: ${esc(r.notes)}</p>`:''}${admin()&&r.status==='synced'?'<button class="btn danger" id="remove-record">Excluir registro</button>':''}${r.status==='error'?'<button class="btn primary" id="correct-record">Conferir e reenviar</button>':''}`);const remove=document.querySelector('#remove-record');if(remove)remove.onclick=()=>removeRecordDialog(r.id,'refuel','FROTA '+r.fleet+' · '+num(r.liters)+' L');const c=document.querySelector('#correct-record');if(c)c.onclick=async()=>{modal.close();editId=r.id;draft=r;view='new';shell()}}
async function showNotifications(){const rs=unread();dialog('Notificações',rs.length?rs.map(r=>`<button class="notice-entry" data-notice="${r.id}"><b>${r.kind==='checklist'?'CHECKLIST · FROTA '+esc(r.fleet)+' · '+checklistStatuses[r.grade]:r.kind?(r.kind==='transfer'?'TRANSFERÊNCIA':'OCORRÊNCIA')+' · LOCAL '+esc(r.local_code):'Frota '+esc(r.fleet)+' · '+num(r.liters)+' L'}</b><small>${esc(r.operator)} · ${new Date(r.received_at).toLocaleString('pt-BR')}</small></button>`).join(''):'<p class="empty">Nenhum novo aviso.</p>');lastChecked=new Date().toISOString();await putMeta(userKey('seen'),lastChecked);document.querySelectorAll('[data-notice]').forEach(b=>b.onclick=()=>{modal.close();const checklist=checklistRecords.find(r=>r.id===b.dataset.notice);if(checklist){navigate('checklists').then(()=>checklistLoading).then(()=>showChecklist(checklist.id));return}const operation=serverOperations.find(o=>o.id===b.dataset.notice);if(operation){navigate(operation.kind==='occurrence'?'occurrences':'operations').then(()=>showOperationDetails(operation.id))}else details(b.dataset.notice)});const badge=document.querySelector('#notifications .badge');if(badge)badge.remove()}
function addFleet(){dialog('Cadastrar frota',`<form id="fleet-form"><div class="form-grid"><label>Código da frota<input name="id" placeholder="Ex.: TR-01" pattern="[A-Za-z0-9_.\-]{1,30}" required maxlength="30"></label><label>Tipo<select name="type"><option>Trator</option><option>Colhedora</option><option>Caminhão</option><option>Outro</option></select></label><label class="full">Nome da máquina<input name="name" placeholder="Ex.: Trator John Deere" required minlength="2" maxlength="80"></label></div><p class="error-message" id="dialog-error"></p><button class="btn primary" type="submit">Cadastrar frota</button></form>`);document.querySelector('#fleet-form').onsubmit=async e=>{e.preventDefault();await adminSave({action:'fleet',...Object.fromEntries(new FormData(e.target))})}}
function accessOptions(member){const permissions=memberPermissions(member);return Object.entries(featureLabels).map(([feature,label])=>`<label><input type="checkbox" name="permission-${feature}" ${permissions[feature]?'checked':''}>${label}</label>`).join('')}
function readAccessOptions(form){return Object.fromEntries(Object.keys(featureLabels).map(feature=>[feature,form.elements['permission-'+feature].checked]))}
function editMemberAccess(member){if(!member)return;dialog('PERMISSÕES · '+esc(member.name),`<form id="member-access-form"><p>${esc(member.username)}</p><label>PERFIL<select name="role"><option value="operator" ${member.role==='operator'?'selected':''}>OPERADOR</option><option value="admin" ${member.role==='admin'?'selected':''}>ADMINISTRADOR</option></select></label><fieldset class="access-options"><legend>FUNÇÕES NO APLICATIVO</legend>${accessOptions(member)}</fieldset><p class="error-message" id="dialog-error" role="alert"></p><button class="btn primary" type="submit">SALVAR PERMISSÕES</button></form>`);document.querySelector('#member-access-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;await adminSave({action:'member-access',email:member.email,role:e.target.elements.role.value,permissions:readAccessOptions(e.target)});button.disabled=false}}
function addMember(){dialog('Adicionar pessoa à equipe',`<form id="member-form"><div class="form-grid"><label class="full">Nome completo<input name="name" required minlength="2" maxlength="120"></label><label class="full">Usuário<input name="username" required minlength="3" maxlength="30" pattern="[A-Za-z0-9][A-Za-z0-9_.-]{2,29}" autocapitalize="characters"></label><label class="full">E-mail<input name="email" type="email" required></label><label class="full">Perfil<select name="role"><option value="operator">Operador</option><option value="admin">Administrador</option></select></label><fieldset class="full access-options"><legend>FUNÇÕES NO APLICATIVO</legend>${accessOptions()}</fieldset></div><p class="error-message" id="dialog-error"></p><button class="btn primary" type="submit">Salvar acesso</button></form>`);document.querySelector('#member-form').onsubmit=async e=>{e.preventDefault();await adminSave({action:'member',...Object.fromEntries(new FormData(e.target)),permissions:readAccessOptions(e.target)})}}
async function adminSave(data){try{await api('admin',{method:'POST',body:JSON.stringify(data)});await refreshSession();modal.close();shell();toast('Cadastro salvo.')}catch(e){document.querySelector('#dialog-error').textContent=e.message}}
async function loadMembers(){try{const {members,removedMembers=[]}=await api('admin');const el=document.querySelector('#members');if(el)el.innerHTML=members.map(m=>`<div class="fleet-row team-row" style="margin:0 22px"><span class="avatar">${esc(m.name.slice(0,1))}</span><div><b>${esc(m.name)}</b><small>${esc(m.username)} · ${esc(m.email)}</small></div><span class="pill" style="margin-left:auto">${m.role==='admin'?'Administrador':'Operador'}</span><span class="team-functions">${Object.entries(memberPermissions(m)).filter(([,enabled])=>enabled).map(([feature])=>featureLabels[feature]).join(' · ')||'SEM FUNÇÕES LIBERADAS'}</span><button class="link-btn" data-member-access="${esc(m.email)}">PERMISSÕES</button><button class="link-btn" data-username-email="${esc(m.email)}" data-username="${esc(m.username)}">Editar usuário</button><button class="link-btn" data-password-email="${esc(m.email)}" data-password-user="${esc(m.username)}">Definir senha</button>${m.email!==session.user.email?`<button class="link-btn" data-remove-member="${esc(m.email)}">REMOVER</button>`:''}</div>`).join('')+(removedMembers.length?`<details style="margin:20px 22px"><summary>USUÁRIOS REMOVIDOS (${removedMembers.length})</summary>${removedMembers.map(m=>`<div class="fleet-row team-row"><div><b>${esc(m.name)}</b><small>${esc(m.username)}</small></div><button class="link-btn" data-restore-member="${esc(m.email)}">RESTAURAR</button></div>`).join('')}</details>`:'');if(el)el.querySelectorAll('[data-member-access]').forEach(b=>b.onclick=()=>editMemberAccess(members.find(m=>m.email===b.dataset.memberAccess)));if(el)el.querySelectorAll('[data-remove-member]').forEach(b=>b.onclick=()=>memberRemovalDialog(members.find(m=>m.email===b.dataset.removeMember)));if(el)el.querySelectorAll('[data-restore-member]').forEach(b=>b.onclick=()=>memberRemovalDialog(removedMembers.find(m=>m.email===b.dataset.restoreMember),true));if(el)el.querySelectorAll('[data-username-email]').forEach(b=>b.onclick=()=>editUsername(b.dataset.usernameEmail,b.dataset.username));if(el)el.querySelectorAll('[data-password-email]').forEach(b=>b.onclick=()=>setMemberPassword(b.dataset.passwordEmail,b.dataset.passwordUser))}catch(e){const el=document.querySelector('#members');if(el)el.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function memberRemovalDialog(member,restore=false){if(!member||!admin())return;dialog(restore?'RESTAURAR USUÁRIO':'REMOVER USUÁRIO',`<form id="member-removal-form"><p><strong>${esc(member.name)} · ${esc(member.username)}</strong></p><p>${restore?'O usuário voltará a ter o perfil e as permissões anteriores.':'O usuário perderá o acesso ao sistema. Os registros enviados serão preservados. Será possível restaurar o acesso depois.'}</p><p class="error-message" id="dialog-error" role="alert"></p><button class="btn primary" type="submit">${restore?'RESTAURAR USUÁRIO':'CONFIRMAR REMOÇÃO'}</button></form>`);document.querySelector('#member-removal-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;await adminSave({action:restore?'member-restore':'member-remove',email:member.email});button.disabled=false}}
async function saveRules(){try{await api('admin',{method:'POST',body:JSON.stringify({action:'rules',rules:{...session.rules,matchMeter:document.querySelector('#rule-match').checked,futureDate:document.querySelector('#rule-future').checked}})});await refreshSession();toast('Regras salvas. A conferência de KM e horímetros continua obrigatória.')}catch(e){toast(e.message)}}
function exportCSV(){const rs=view==='dashboard'?dashboardRecords():filtered();const cell=v=>{v=String(v??'').toLocaleUpperCase('pt-BR');if(/^[=+@\-]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"'};const fields=['date','fleet','previous_engine','engine','previous_elevator','elevator','previous_km','km','local_code','material_code','recorder_start','recorder_end','start','end','liters','operator','status','tank_capacity_at_record','capacity_warning_confirmed','is_test'];const csv='\uFEFF'+['DATA;FROTA;MOTOR ANTERIOR;MOTOR ATUAL;ELEVADOR ANTERIOR;ELEVADOR ATUAL;KM ANTERIOR;KM ATUAL;LOCAL;MATERIAL;REGISTRADORA INICIAL;REGISTRADORA FINAL;INÍCIO REG.;FINAL REG.;LITROS;ASSINATURA;SITUAÇÃO;CAPACIDADE L;ACIMA DA CAPACIDADE;TESTE',...rs.map(r=>fields.map(k=>{const value=k==='is_test'?(isTestRecord(r)?'SIM':'NÃO'):exportReading(r,k);return cell(typeof value==='number'?String(value).replace('.',','):value)}).join(';'))].join('\r\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=`abastecimentos-${today()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Arquivo CSV exportado para abrir no Excel.')}
async function printRecords(){const rs=filtered();const w=window.open('','_blank');if(!w)return toast('Permita abrir a janela de impressão no navegador.');w.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Controle de combustível de frotas</title><style>@page{size:A4 landscape;margin:12mm}body{font:11px Arial;color:#111;text-transform:uppercase}h1{font-size:18px;text-align:center;margin:24px}p{font-size:10px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #555;padding:9px 6px}th{font-size:10px;background:#eee}small{color:#666}${reportHeaderStyles}</style></head><body><table><thead><tr><td class="report-heading-cell" colspan="10">${reportHeaderHTML('CONTROLE DE ABASTECIMENTO FROTAS')}<p>${rs.length} REGISTROS</p></td></tr><tr>${['DATA','FROTA','MOTOR (ANTERIOR / ATUAL)','ELEVADOR (ANTERIOR / ATUAL)','KM (ANTERIOR / ATUAL)','INÍCIO REG.','FINAL REG.','LITROS','ASSINATURA','SITUAÇÃO'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rs.map(r=>`<tr>${[date(r.date),r.fleet,printReading(r,'engine'),printReading(r,'elevator'),printReading(r,'km'),r.start==null?'—':num(r.start),r.end==null?'—':num(r.end),num(r.liters),r.operator,r.status==='synced'?'Confirmado':'Pendente'].map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table><p><small>Assinatura conforme o nome informado no campo ou a conta autenticada em registros anteriores. Registros pendentes aguardam confirmação do servidor.</small></p></body></html>`);try{await finishReportPrint(w)}catch{w.close();toast('Não foi possível carregar a logo para imprimir. Tente novamente.')}}
async function install(){if(installPrompt){await installPrompt.prompt();installPrompt=null}else toast('No Chrome do Android, abra o menu ⋮ e escolha “Adicionar à tela inicial” ou “Instalar aplicativo”.')}
async function prepareOffline(){
 if(!('serviceWorker'in navigator))return;
 const checkCache=async()=>{const cache=await caches.open('diesel-pages-v1');const required=['./index.html','./app.js','./backend.js','./config.js','./vendor.js','./style.css','./theme.js','./fuel-utils.js','./text-case.js','./fleets.json'];return (await Promise.all(required.map(p=>cache.match(new URL(p,location.href).href)))).every(Boolean)};
 try{
  ready=await checkCache();document.body.dataset.offlineReady=String(ready);if(ready&&!navigator.onLine)return;
  const reg=await navigator.serviceWorker.register('./sw.js');if(navigator.onLine)await reg.update();
  const worker=reg.installing||reg.waiting;
  if(worker&&!['installed','activated'].includes(worker.state))await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Preparo offline demorou.')),30000);const check=()=>{if(['installed','activated'].includes(worker.state)){clearTimeout(timer);resolve()}else if(worker.state==='redundant'){clearTimeout(timer);reject(Error('Arquivos offline indisponíveis.'))}};worker.addEventListener('statechange',check);check()});
  await navigator.serviceWorker.ready;ready=await checkCache();if(navigator.storage?.persist)try{await navigator.storage.persist()}catch{}
 }catch{ready=await checkCache();if(!ready)toast('Não foi possível preparar o modo offline neste navegador.')}
 document.body.dataset.offlineReady=String(ready);updateConnection();
}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
navigator.serviceWorker?.addEventListener('message',e=>{if(e.data?.type==='sync')sync()});
window.addEventListener('online',()=>sync());
window.addEventListener('offline',()=>{connected=false;updateConnection()});
function bindSignOut(){document.querySelectorAll('[data-signout]').forEach(a=>a.onclick=async e=>{e.preventDefault();await saveDraft();await signOut();await putMeta('session',null);location.href='./admin.html'})}
function loginScreen(message=''){app.innerHTML=`<section class="card boot-login"><img src="./logo-abencoada.png" alt="Abençoada"><h1>Entrar</h1><form id="login-form"><label>Usuário<input name="username" type="text" autocomplete="username" autocapitalize="characters" spellcheck="false" required maxlength="254" placeholder="Digite seu usuário"></label><label>Senha<input name="password" type="password" autocomplete="current-password" required style="text-transform:none"></label><p class="error-message" id="login-error" role="alert">${esc(message)}</p><button class="btn primary" type="submit">Entrar</button></form></section>`;document.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const values=new FormData(e.target);await signIn(values.get('username'),values.get('password'));await boot()}catch(error){document.querySelector('#login-error').textContent=error.message}finally{b.disabled=false}}}
async function boot(){try{if(!db)db=await openDB();prepareOffline();if(fieldMode){location.replace(new URL('./admin.html',location.href));return}if(!isConfigured()){app.innerHTML='<section class="card boot-login"><img src="./logo-abencoada.png" alt="Abençoada"><h1>Sistema em configuração</h1><p>O gestor precisa conectar o banco para liberar o acesso.</p></section>';return}const authId=await getAuthUserId();if(!authId){session=null;loginScreen();return}session=await meta('session');if(session?.user.id!==authId)session=null;try{await refreshSession()}catch(e){if(e.status===401||e.status===403||!session){session=null;loginScreen(e.message);return}connected=false}await loadLocal();view=fieldMode?'new':admin()?'dashboard':'denied';shell();sync();clearInterval(boot.interval);boot.interval=setInterval(()=>sync(),15000)}catch(e){app.innerHTML=`<section class="card boot-login"><h1>Armazenamento indisponível</h1><p>${esc(e.message)}</p></section>`}}
boot();

function editUsername(email,username){dialog('Nome de usuário',`<form id="username-form"><label>Usuário<input name="username" required minlength="3" maxlength="30" pattern="[A-Za-z0-9][A-Za-z0-9_.-]{2,29}" autocapitalize="characters" value="${esc(username)}"></label><p class="error-message" id="dialog-error"></p><button class="btn primary" type="submit">Salvar usuário</button></form>`);document.querySelector('#username-form').onsubmit=async e=>{e.preventDefault();await adminSave({action:'member-username',email,username:new FormData(e.target).get('username')})}}

async function bootField(){
 let device=await meta('field-device');if(!device){device=crypto.randomUUID();await putMeta('field-device',device)}
 let cached=await meta('field-session');
 if(!cached){const response=await fetch('./fleets.json');if(!response.ok)throw Error('Abra o sistema uma vez com internet para carregar as frotas.');cached={fleets:(await response.json()).map(f=>({...f,active:true})),rules:{matchMeter:false,futureDate:false}};await putMeta('field-session',cached)}
 session={...cached,user:{id:'field:'+device,name:'',role:'field'}};
 await loadLocal();view='new';shell();sync();clearInterval(boot.interval);boot.interval=setInterval(()=>sync(),15000);
}

async function fleetQrDialog(id){const fleet=session.fleets.find(f=>f.id===id);if(!fleet)return;try{const image=await makeFleetQr(fleet);dialog('QR Code · Frota '+esc(id),`<div style="text-align:center"><img src="${image}" alt="QR Code da frota ${esc(id)}" style="width:min(100%,300px);background:white;border:12px solid white;border-radius:8px"><h3>Frota ${esc(id)}</h3><p>${esc(fleet.name)}</p><button class="btn primary" id="print-one-qr">Imprimir etiqueta</button><a class="btn" download="frota-${esc(id)}.png" href="${image}">Baixar QR Code</a></div>`);document.querySelector('#print-one-qr').onclick=()=>printFleetQrs([fleet])}catch{toast('Não foi possível gerar o QR Code.')}}
async function printFleetQrs(fleets){if(!fleets.length)return toast('Não há frotas para imprimir.');const win=window.open('','_blank');if(!win)return toast('Permita abrir a janela de impressão.');const issuedAt=new Date();try{const labels=await Promise.all(fleets.map(async f=>`<article><h1>FROTA ${esc(f.id)}</h1><img src="${await makeFleetQr(f)}" alt="QR Code da frota ${esc(f.id)}"><p>${esc(f.name)}</p><small>ABENÇOADA AGRÍCOLA</small></article>`));const rows=[];for(let i=0;i<labels.length;i+=2)rows.push(`<tr><td><div class="labels-grid">${labels.slice(i,i+2).join('')}</div></td></tr>`);win.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>QR Codes das frotas</title><style>@page{size:A4;margin:12mm}body{font-family:Arial;color:#111;text-transform:uppercase;margin:0}table{width:100%;border-collapse:collapse}td{padding:0}tbody tr{break-inside:avoid}.labels-grid{display:grid;grid-template-columns:1fr 1fr;gap:10mm;margin-bottom:8mm}article{border:1px solid #555;text-align:center;padding:8mm;break-inside:avoid}h1{font-size:22px;margin:0}article img{display:block;width:55mm;height:55mm;margin:3mm auto}p{font-size:13px;margin:5px}small{font-size:11px}${reportHeaderStyles}</style></head><body><table><thead><tr><td class="report-heading-cell">${reportHeaderHTML('QR CODES DAS FROTAS',issuedAt)}</td></tr></thead><tbody>${rows.join('')}</tbody></table></body></html>`);await finishReportPrint(win)}catch{win.close();toast('Não foi possível preparar as etiquetas.')}}

function recordReadingDetails(r){if(r.capture_mode!=='quick')return [['Horímetro motor',num(r.engine)+' h'],['Horímetro elevador',num(r.elevator)+' h'],['KM',num(r.km)]];return Object.keys(meterLabels).filter(k=>r.measured_fields?.[k]).flatMap(k=>[[meterLabels[k]+' anterior',num(r.previous_readings?.[k])],[meterLabels[k]+' atual',num(r[k])]]).concat([['Registro anterior',r.previous_readings?.recordedAt?new Date(r.previous_readings.recordedAt).toLocaleString('pt-BR'):'Primeiro registro']])}
function exportReading(r,k){if(k.startsWith('previous_')){const meter=k.slice(9);return r.capture_mode==='quick'&&r.measured_fields?.[meter]?r.previous_readings?.[meter]:''}if(['km','engine','elevator'].includes(k)&&r.capture_mode==='quick'&&!r.measured_fields?.[k])return '';return r[k]}
function printReading(r,k){if(r.capture_mode!=='quick')return num(r[k]);return r.measured_fields?.[k]?num(r.previous_readings?.[k])+' / '+num(r[k]):'—'}
function meterFieldsDialog(id){const fleet=session.fleets.find(f=>f.id===id);if(!fleet)return;const selected=fleetMeters(fleet);dialog('Leituras · Frota '+esc(id),`<form id="meter-fields-form">${Object.entries(meterLabels).filter(([k])=>k!=='elevator'||canUseElevator(fleet)).map(([k,label])=>`<label class="setting-row"><input type="checkbox" name="${k}" ${selected[k]?'checked':''}>${label}</label>`).join('')}<p class="error-message" id="dialog-error"></p><button class="btn primary" type="submit">Salvar leituras</button></form>`);document.querySelector('#meter-fields-form').onsubmit=async e=>{e.preventDefault();const meterFields=Object.fromEntries(Object.keys(meterLabels).map(k=>[k,Boolean(e.target.elements[k]?.checked)]));await adminSave({action:'fleet-meters',id,meterFields})}}

function setMemberPassword(email,username){
 dialog('Definir senha · '+esc(username),`<form id="password-form"><p>Cria o acesso se a conta ainda não existir ou substitui a senha atual. Usuário: <b>${esc(username)}</b>.</p><label>Nova senha<input name="password" type="password" autocomplete="new-password" minlength="6" maxlength="128" required style="text-transform:none"></label><label>Confirmar senha<input name="confirmation" type="password" autocomplete="new-password" minlength="6" maxlength="128" required style="text-transform:none"></label><p class="error-message" id="dialog-error" role="alert"></p><button class="btn primary" type="submit">Salvar senha</button></form>`);
 document.querySelector('#password-form').onsubmit=async e=>{e.preventDefault();const values=new FormData(e.target),password=values.get('password');const error=document.querySelector('#dialog-error');if(password!==values.get('confirmation')){error.textContent='As senhas devem ser iguais.';return}const button=e.target.querySelector('button');button.disabled=true;try{const result=await api('team-password',{method:'POST',body:JSON.stringify({email,password})});e.target.reset();modal.close();toast(result.created?'Acesso criado. Entre com o usuário e a senha definidos.':'Senha atualizada.')}catch(failure){error.textContent=failure.message}finally{button.disabled=false}};
}

function operationFiltersHTML(kind){const f=operationFilters[kind];return `<div class="table-tools operation-filters"><label>FROTA<input id="operation-fleet" value="${esc(f.fleet)}" placeholder="DIGITE A FROTA" inputmode="numeric" maxlength="30" autocomplete="off"></label><label>FUNCIONÁRIO<input id="operation-operator" value="${esc(f.operator)}" placeholder="NOME DO FUNCIONÁRIO" autocomplete="off"></label><label>DE<input id="operation-from" type="date" value="${esc(f.from)}"></label><label>ATÉ<input id="operation-to" type="date" value="${esc(f.to)}"></label><button class="btn" id="clear-operation-filters">LIMPAR FILTROS</button></div><div id="operation-rows"></div>`}
function operationsListHTML(operations,kind){const f=operationFilters[kind],normalize=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase(),items=operations.filter(o=>{const day=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo'}).format(new Date(o.created_at));return o.kind===kind&&(!f.fleet||normalize(o.fleet).includes(normalize(f.fleet.trim())))&&(!f.operator||normalize(o.operator).includes(normalize(f.operator.trim())))&&(!f.from||day>=f.from)&&(!f.to||day<=f.to)});return items.length?items.map(o=>`<div class="fleet-row operation-entry"><div><b>${esc(o.operator)}</b>${o.fleet?`<p>FROTA ${esc(o.fleet)}</p>`:''}<small>${esc(new Date(o.created_at).toLocaleString('pt-BR'))} · LOCAL ${esc(o.local_code)} · MATERIAL ${esc(o.material_code)}</small><p class="operation-notes">${kind==='transfer'?'NOVO LOCAL: '+esc(o.destination):esc(o.notes)}</p>${kind==='transfer'&&o.recorder_start!=null?`<p>REGISTRADORA: ${num(o.recorder_start,2)} → ${num(o.recorder_end,2)}<br>DESDE O ÚLTIMO REGISTRO: ${num(o.recorder_liters,2)} L</p>`:''}<div class="operation-actions"><button class="btn" data-operation-detail="${esc(o.id)}">${o.has_photo?'VER FOTO E DETALHES':'VER DETALHES'}</button><button class="btn danger" data-remove-operation="${esc(o.id)}">EXCLUIR</button></div></div></div>`).join(''):'<p class="empty">NENHUM REGISTRO NESTE FILTRO.</p>'}
function renderOperationRows(){const kind=view==='occurrences'?'occurrence':view==='operations'?'transfer':null,el=document.querySelector('#operation-rows');if(!kind||!el)return;el.innerHTML=operationsListHTML(serverOperations,kind);el.querySelectorAll('[data-operation-detail]').forEach(b=>b.onclick=()=>showOperationDetails(b.dataset.operationDetail));el.querySelectorAll('[data-remove-operation]').forEach(b=>b.onclick=()=>requestOperationRemoval(b.dataset.removeOperation))}
function bindOperationFilters(kind){for(const key of ['fleet','operator','from','to']){const input=document.querySelector('#operation-'+key);input[['fleet','operator'].includes(key)?'oninput':'onchange']=()=>{operationFilters[kind][key]=input.value;renderOperationRows()}}document.querySelector('#clear-operation-filters').onclick=()=>{operationFilters[kind]={fleet:'',operator:'',from:'',to:''};const el=document.querySelector('#operations-list');el.innerHTML=operationFiltersHTML(kind);bindOperationFilters(kind);renderOperationRows()}}
async function loadOperationsList(){const kind=view==='occurrences'?'occurrence':'transfer';try{const data=await api('operations-admin');serverOperations=data.operations;await putMeta(userKey('operations'),serverOperations);const el=document.querySelector('#operations-list');if(!el||(view==='occurrences'?'occurrence':view==='operations'?'transfer':null)!==kind)return;el.innerHTML=operationFiltersHTML(kind);bindOperationFilters(kind);renderOperationRows()}catch(e){const el=document.querySelector('#operations-list');if(el)el.textContent=e.message}}
async function showOperationDetails(id){const operation=serverOperations.find(o=>o.id===id);if(!operation)return;dialog(operation.kind==='occurrence'?'Ocorrência':'Transferência',`<dl class="detail-grid"><div><dt>FROTA</dt><dd>${esc(operation.fleet||'NÃO INFORMADA')}</dd></div><div><dt>OPERADOR</dt><dd>${esc(operation.operator)}</dd></div><div><dt>DATA E HORA</dt><dd>${esc(new Date(operation.created_at).toLocaleString('pt-BR'))}</dd></div><div><dt>LOCAL</dt><dd>${esc(operation.local_code)}</dd></div><div><dt>MATERIAL</dt><dd>${esc(operation.material_code)}</dd></div></dl><p class="operation-notes">${operation.kind==='occurrence'?esc(operation.notes):'NOVO LOCAL: '+esc(operation.destination)}</p><button class="btn danger" id="remove-operation">Excluir registro</button>${operation.has_photo?'<div id="operation-photo-content" role="status">CARREGANDO FOTO…</div>':''}`);document.querySelector('#remove-operation').onclick=()=>requestOperationRemoval(id);if(operation.has_photo)await loadOperationPhoto(id)}

function updateWebCapacity(){const form=document.querySelector('#fuel-form'),el=document.querySelector('#capacity-warning');if(!form||!el)return;const fleet=session.fleets.find(f=>f.id===form.elements.fleet.value.trim().toUpperCase()),warning=capacityWarning(fleet,Number(form.elements.liters.value));el.hidden=!warning;el.textContent=warning?'Confira: '+num(warning.liters,2)+' L ultrapassa a capacidade cadastrada de '+num(warning.capacity,2)+' L.':''}

async function loadOperationPhoto(id){
 const content=document.querySelector('#operation-photo-content');
 try{const data=await api('occurrence-photo?id='+encodeURIComponent(id));if(typeof data.photo!=='string'||!/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(data.photo))throw Error('Foto indisponível.');content.innerHTML=`<img class="operation-photo" src="${esc(data.photo)}" alt="Foto da ocorrência">`}
 catch(error){content.textContent=error.message}
}

async function removeRecordDialog(id,kind,label){
 dialog('Excluir registro',`<p><b>${esc(label)}</b></p><form id="remove-record-form"><label>Motivo<textarea name="reason" required minlength="3" maxlength="500" rows="3"></textarea></label><p>O registro sai das listas e dos totais. Você pode restaurá-lo em EXCLUÍDOS. ${kind==='occurrence'?'':'A leitura física da registradora permanece; ajuste-a nas configurações se estiver errada.'}</p><p class="error" id="remove-error"></p><button class="btn danger">Confirmar exclusão</button></form>`);
 document.querySelector('#remove-record-form').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;try{await api('record-controls',{method:'POST',body:JSON.stringify({action:'remove',id,kind,reason:event.target.elements.reason.value})});await refreshAfterRecordChange();modal.close();toast('Registro excluído.')}catch(error){document.querySelector('#remove-error').textContent=error.message;button.disabled=false}};
}
async function refreshAfterRecordChange(){await refreshSession();await fetchRecords();const data=await api('operations-admin');serverOperations=data.operations;await putMeta(userKey('operations'),serverOperations);shell()}
async function showRemovedRecords(){
 try{const data=await api('record-controls');dialog('Registros excluídos',data.records.length?data.records.map(r=>`<div class="removed-entry"><b>${r.kind==='refuel'?'FROTA '+esc(r.fleet)+' · '+num(r.liters)+' L':r.kind==='transfer'?'TRANSFERÊNCIA':'OCORRÊNCIA'}</b><p>${esc(r.operator)} · ${esc(new Date(r.created_at).toLocaleString('pt-BR'))}</p><p>${esc(r.removal_reason)}</p><small>EXCLUÍDO POR ${esc(r.removed_by_name)} · ${esc(new Date(r.removed_at).toLocaleString('pt-BR'))}</small><button class="btn" data-restore="${esc(r.id)}" data-kind="${esc(r.kind)}">Restaurar</button></div>`).join(''):'<p class="empty">Nenhum registro excluído.</p>');document.querySelectorAll('[data-restore]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api('record-controls',{method:'POST',body:JSON.stringify({action:'restore',id:button.dataset.restore,kind:button.dataset.kind})});await refreshAfterRecordChange();await showRemovedRecords();toast('Registro restaurado.')}catch(error){toast(error.message);button.disabled=false}})}catch(error){toast(error.message)}
}

function requestOperationRemoval(id){const operation=serverOperations.find(o=>o.id===id);if(!operation)return;removeRecordDialog(id,operation.kind,(operation.kind==='occurrence'?'OCORRÊNCIA':'TRANSFERÊNCIA')+' · '+operation.operator+' · '+new Date(operation.created_at).toLocaleString('pt-BR'))}

function cacheChecklists(records){checklistRecords=records.map(r=>({...r,kind:'checklist'}));putMeta(userKey('checklists'),checklistRecords).catch(()=>{})}
async function refreshChecklists(){const data=await api('checklists-admin');const known=new Set(checklistRecords.map(r=>r.id)),fresh=data.records.filter(r=>!known.has(r.id)&&r.received_at>lastChecked);cacheChecklists(data.records);if(fresh.length){const issues=checklistOpenItems(fresh);toast(fresh.length+' NOVO(S) CHECKLIST(S)'+(issues.length?' · '+issues.length+' ITENS PARA CONFERIR.':'.'));if('Notification'in window&&Notification.permission==='granted'&&document.hidden){const reg=await navigator.serviceWorker?.getRegistration();if(reg)await reg.showNotification('NOVO CHECKLIST · '+checklistStatuses[fresh[0].grade],{body:'FROTA '+fresh[0].fleet+' · '+fresh[0].operator,icon:'./icon-192.png',tag:'checklist-'+fresh[0].id})}}}
function checklistAlertHTML(){const open=checklistOpenItems(checklistRecords);if(!open.length)return '';return `<div class="banner checklist-alert-banner"><b>CHECKLIST: ${open.filter(a=>a.status==='CRITICO').length} ITENS CRÍTICOS · ${open.filter(a=>a.status==='ATENCAO').length} ATENÇÃO</b><button class="btn" id="view-checklist-alerts">VER ITENS EM ABERTO</button></div>`}
